<script setup lang="ts">
import {computed,ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import {definiteGovernanceRejection} from '@/shared/stored-value-governance-errors';import {idempotencyKey} from '@shared/net/http-client';import {money} from '@shared/utils/money';import type {SvApproval} from '@/api/stored-value-governance';
const {t}=useI18n();const management=ref(''),items=ref<SvApproval[]>([]),status=ref('PENDING'),cursor=ref<string|null>(null),current=ref<SvApproval|null>(null),reason=ref(''),loading=ref(true),busy=ref(false),failed=ref(false),error=ref('');let generation=0;
const tabs=computed(()=>['PENDING','APPROVED','RETURNED','ALL'].map(key=>({key,label:t(`svGov.states.${key}`)})));
type Pending={no:string;key:string;body:{managementNo:string;decision:{decision:'APPROVE'|'RETURN';reason:string;expectedRevision:number}}};const pending=ref<Pending|null>(null),storage=computed(()=>`sv-approval-pending:${management.value}`);
async function load(append=false){const token=++generation;loading.value=true;failed.value=false;try{const page=await api.mSvApprovals({managementNo:management.value,status:status.value==='ALL'?undefined:status.value,cursor:append?cursor.value||undefined:undefined,size:20});if(token!==generation)return;items.value=append?[...items.value,...page.records]:page.records;cursor.value=page.nextCursor;const saved=uni.getStorageSync(storage.value);if(saved){pending.value=JSON.parse(String(saved)) as Pending;current.value=await api.mSvApproval(pending.value.no,management.value);reason.value=pending.value.body.decision.reason;}}catch(e){failed.value=true;error.value=(e as Error).message}finally{if(token===generation)loading.value=false}}
function select(value:string){if(busy.value||pending.value)return;status.value=value;void load()}
async function open(value:SvApproval){if(pending.value)return;error.value='';reason.value='';try{current.value=await api.mSvApproval(value.approvalNo,management.value)}catch(e){error.value=(e as Error).message}}
async function decide(value:'APPROVE'|'RETURN'){if(busy.value||!current.value)return;error.value='';try{if(!pending.value){if(!reason.value.trim())throw Error(t('svGov.reasonRequired'));const p:Pending={no:current.value.approvalNo,key:idempotencyKey(),body:{managementNo:management.value,decision:{decision:value,reason:reason.value.trim(),expectedRevision:current.value.revision}}};uni.setStorageSync(storage.value,JSON.stringify(p));pending.value=p;}busy.value=true;const p=pending.value;current.value=await api.mSvApprovalDecide(p.no,p.body,p.key);uni.removeStorageSync(storage.value);pending.value=null;await load()}catch(e){error.value=(e as Error).message;await reconcile(e);}finally{busy.value=false}}
async function reconcile(error:unknown){const p=pending.value;if(!p)return;try{const actual=await api.mSvApproval(p.no,management.value);let done=['RETURNED','STALE'].includes(actual.status);
 if(actual.status==='APPROVED'){const activity=await (actual.scopeType==='BRAND'?api.mSvBrandActivity(actual.scopeNo!,actual.activityNo,{managementNo:management.value,currency:actual.definition.currency}):api.mSvActivity(actual.storeNo!,actual.activityNo,{managementNo:management.value,currency:actual.definition.currency}));done=activity.submission?.linkNo===actual.linkNo&&['ACTIVE','STALE','BLOCKED_POLICY','STOPPED'].includes(activity.submission.state);}
 if(done||actual.status==='PENDING'&&actual.revision===p.body.decision.expectedRevision&&definiteGovernanceRejection(error)){current.value=actual;uni.removeStorageSync(storage.value);pending.value=null;}
 }catch{/* A committed approval may still need its original publish retry. */}}
onLoad(q=>{management.value=q?.m||'';void load()});
</script>
<template><sh-scaffold title-key="svGov.approvals" :pending="loading&&!items.length" :failed="failed" @retry="load(false)"><sh-tabs :items="tabs" :active="status" @change="select($event)"/><view v-for="a in items" :key="a.approvalNo" data-testid="approval-card" class="sh-card sh-hit" @tap="open(a)"><view class="sh-row sh-row--between"><text class="txt-title">{{a.definition.name}}</text><text class="sh-chip">{{t(`svGov.states.${a.status}`)}}</text></view><sh-kv v-for="tier in a.definition.rule.tiers" :key="tier.tierNo" :label="money(tier.payAmountMinor,a.definition.currency)" between>{{t('svGov.give')}} {{money(tier.bonusAmountMinor,a.definition.currency)}}</sh-kv></view><sh-empty v-if="!loading&&!items.length" :text="t('svGov.noApprovals')"/><view v-if="cursor&&!loading" class="sh-btn sh-btn--soft" @tap="load(true)">{{t('svGov.more')}}</view>
 <sh-sheet :visible="!!current" :title="current?.definition.name||t('svGov.approvals')" @close="!busy&&!pending&&(current=null)"><template v-if="current"><view class="sh-card"><text class="sh-chip">{{t(`svGov.states.${current.status}`)}}</text><sh-kv v-for="tier in current.definition.rule.tiers" :key="tier.tierNo" :label="money(tier.payAmountMinor,current.definition.currency)" between>{{t('svGov.give')}} {{money(tier.bonusAmountMinor,current.definition.currency)}}</sh-kv><text v-if="current.reason" class="txt-sub sh-muted">{{current.reason}}</text></view><view v-if="current.status==='PENDING'||pending" class="field"><text class="field__label">{{t('svGov.reason')}}</text><textarea data-testid="approval-reason" v-model="reason" class="field__input" maxlength="255" :disabled="busy||!!pending"/></view><text v-if="error" class="sh-hint">{{error}}</text><text v-if="pending" class="sh-hint">{{t('svGov.unknown')}}</text><view data-testid="approval-retry" v-if="pending" class="sh-btn" :class="{'is-disabled':busy}" @tap="decide(pending.body.decision.decision)">{{t('svGov.retry')}}</view><view v-else-if="current.status==='PENDING'" class="sh-row"><view class="sh-btn sh-btn--soft sh-fill" :class="{'is-disabled':busy}" @tap="decide('RETURN')">{{t('svGov.return')}}</view><view data-testid="approval-approve" class="sh-btn sh-fill" :class="{'is-disabled':busy}" @tap="decide('APPROVE')">{{t('svGov.approve')}}</view></view></template></sh-sheet>
 </sh-scaffold></template>
